/**
 * The static demo's My numbers and weekly session. Both are computed by Ordnung's own Python code over
 * the mock letters (`data/numbers.ts`, generated by `scripts/gen_mock_numbers.py`); here they only follow
 * what the visitor does: a letter deleted in the demo takes its numbers along, a to-do marked done leaves
 * its step (and the ending moves on to the next day to act), and "Finish" / "Not now" are remembered for
 * this mock database.
 */
import type { CallSheet, IdentityDocument, Item, LetterRef, MyNumber, NumbersPage, OpenCase, WeekEntry, WeekStep, WeeklySession } from "@/api/types";
import type { MockDb } from "./db";
import { MEMBER_NOTES, MOCK_NUMBER_LETTERS, MOCK_NUMBERS, MOCK_WEEK, MOCK_WEEK_DEADLINES } from "./data/numbers";

interface WeekState {
  lastSession: string | null;
  dismissed: string | null;
}

const weekStates = new WeakMap<MockDb, WeekState>();

function stateOf(db: MockDb): WeekState {
  let state = weekStates.get(db);
  if (!state) {
    state = { lastSession: null, dismissed: null };
    weekStates.set(db, state);
  }
  return state;
}

const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v)) as T;

/** Whose a letter is when it is no one else's: the person's own (`also_for`'s "me"). */
const ME = "me";

/**
 * My numbers of the letters still in the demo. Once the visitor files a letter for someone of the household, its
 * numbers move to their *About* group as `ordnung/numbers.py` moves them (`regroup`); without one the page is the
 * generated one, following deleted letters.
 */
export function mockNumbers(db: MockDb): NumbersPage {
  const live = new Set(db.liveDocuments().map((d) => d.id));
  const members = new Set(db.state.household.members.map((m) => m.id));
  const filed = Object.fromEntries(Object.entries(db.state.household.links).filter(([doc, link]) => live.has(doc) && members.has(link)));
  return Object.keys(filed).length ? regroup(db, live, filed) : alone(live);
}

/** The person's page alone: a number goes with its latest letter. */
function alone(live: Set<string>): NumbersPage {
  const shown = (n: MyNumber | null | undefined): n is MyNumber => Boolean(n && (!n.letter || live.has(n.letter.id)));
  const openCase = (c: OpenCase): OpenCase | null => {
    const references = c.references.filter(shown);
    return references.length && (!c.letter || live.has(c.letter.id)) ? { ...c, references } : null;
  };
  const data = clone(MOCK_NUMBERS);
  const cases = data.open_cases.map(openCase).filter((c): c is OpenCase => c !== null);
  const sheets = data.organisations
    .map((s): CallSheet => ({
      ...s,
      numbers: s.numbers.filter(shown),
      their_numbers: s.their_numbers.filter(shown),
      open_cases: s.open_cases.map(openCase).filter((c): c is OpenCase => c !== null),
      last_letter: s.last_letter && live.has(s.last_letter.id) ? s.last_letter : null,
    }))
    .filter((s) => s.numbers.length || s.open_cases.length);
  return {
    ...data,
    about_you: data.about_you.filter(shown),
    documents: data.documents
      .filter((d) => !d.letter || live.has(d.letter.id))
      .map((d) => ({ ...d, number: shown(d.number) ? d.number : null })),
    organisations: sheets,
    open_cases: cases,
  };
}

/** A letter as the page names it (`numbers._letter_ref`). */
function letterRef(db: MockDb, id: string): LetterRef | null {
  const d = db.document(id);
  return d ? { id: d.id, title: d.title || d.filename, date: d.doc_date ?? d.received_date ?? d.created_at.slice(0, 10), kind: d.kind } : null;
}

/**
 * The page with letters filed for people of the household (`filed`: letter → person), as `ordnung/numbers.py` builds
 * it: each person's numbers and documents from their letters (`MOCK_NUMBER_LETTERS`), a person's entries under keys of
 * their own (`<key>:<person>`), the person's keeping theirs; `filed_for` where all of a call sheet's number's, a case
 * reference's or a case's letters are one person's; `also_for` where two people's letters show a number.
 */
function regroup(db: MockDb, live: Set<string>, filed: Record<string, string>): NumbersPage {
  const page = clone(MOCK_NUMBERS);
  const order = [ME, ...db.state.household.members.map((m) => m.id)];
  const personOf = (doc: string | null | undefined) => (doc && filed[doc]) || ME;
  const lettersOf = (prefix: string, key: string, fallback?: string | null) =>
    (MOCK_NUMBER_LETTERS[`${prefix}:${key}`] ?? (fallback ? [fallback] : [])).filter((id) => live.has(id));
  /** One number split by whose letters show it: person → the number as their entry. */
  const split = (n: MyNumber): Map<string, MyNumber> => {
    const byPerson = new Map<string, string[]>();
    for (const id of lettersOf("you", n.key, n.letter?.id)) byPerson.set(personOf(id), [...(byPerson.get(personOf(id)) ?? []), id]);
    const entries = new Map<string, MyNumber>();
    for (const person of order) {
      const ids = byPerson.get(person);
      if (ids?.length) entries.set(person, { ...n, key: person === ME ? n.key : `${n.key}:${person}`, letter: letterRef(db, ids[0]!), letters: ids.length });
    }
    return entries;
  };
  const about = new Map(order.map((person): [string, MyNumber[]] => [person, []]));
  const documents = new Map(order.map((person): [string, IdentityDocument[]] => [person, []]));
  const alsoFor: Record<string, string[]> = {};
  const note = (person: string, d: IdentityDocument) => (person === ME || !d.note ? d.note : (MEMBER_NOTES[d.note] ?? d.note));
  const shared = (entries: Map<string, MyNumber>) => {
    if (entries.size < 2) return;
    for (const [person, n] of entries) alsoFor[n.key] = [...entries.keys()].filter((other) => other !== person);
  };
  for (const n of page.about_you) {
    const entries = split(n);
    for (const [person, entry] of entries) about.get(person)!.push(entry);
    shared(entries);
  }
  for (const d of page.documents) {
    const entries = d.number ? split(d.number) : new Map<string, MyNumber>();
    if (d.item_id) {
      // a document goes with its expiry to-do's letter (one of no letter is the person's)
      const item = db.state.items.find((i) => i.id === d.item_id);
      if (item?.doc_id && !live.has(item.doc_id)) continue;
      const person = personOf(item?.doc_id);
      documents.get(person)!.push({ ...d, number: entries.get(person) ?? null, note: note(person, d) });
    } else {
      for (const [person, number] of entries) documents.get(person)!.push({ ...d, key: person === ME ? d.key : `${d.key}:${person}`, number, letter: number.letter, note: note(person, d) });
    }
    shared(entries);
  }
  const base = alone(live);
  const filedFor: Record<string, string> = {};
  const onlyOne = (ids: string[]) => {
    const people = new Set(ids.map(personOf));
    const [person] = people;
    return people.size === 1 && person !== ME ? person : undefined;
  };
  const sheetNumbers = base.organisations.flatMap((s) => s.numbers);
  const references = base.open_cases.flatMap((c) => c.references);
  for (const n of [...sheetNumbers, ...references]) {
    const person = onlyOne(lettersOf("sheet", n.key, n.letter?.id));
    if (person) filedFor[n.key] = person;
  }
  for (const c of base.open_cases) {
    const person = onlyOne(lettersOf("case", c.key, c.letter?.id));
    if (person) filedFor[c.key] = person;
  }
  const named = new Set([...Object.values(filedFor), ...Object.values(alsoFor).flat()]);
  return {
    ...base,
    about_you: about.get(ME)!,
    documents: documents.get(ME)!,
    household: db.state.household.members
      .map((m) => ({ id: m.id, name: m.name, about: about.get(m.id)!, documents: documents.get(m.id)! }))
      .filter((p) => p.about.length || p.documents.length || named.has(p.id)),
    filed_for: filedFor,
    also_for: alsoFor,
  };
}

/** Whether a to-do's date or amount still waits to be compared with its letter (`unconfirmed_reason`). */
export function unconfirmed(item: Pick<Item, "grounding" | "evidence">): boolean {
  if (item.grounding === "user") return false;
  return item.evidence.some((e) => !e.value_consistent) || item.grounding === "unverified" || item.grounding === "model_read";
}

/**
 * Whether a row still stands in the demo: its letter kept, its to-do still open (in Compare with the letter:
 * still unconfirmed — "The date looks right" takes it off), its draft there, what it waits for not settled.
 */
function stillThere(db: MockDb, entry: WeekEntry, step?: WeekStep["id"]): boolean {
  if (entry.doc_id && !db.document(entry.doc_id)) return false;
  switch (entry.ref.type) {
    case "document":
      return Boolean(db.document(entry.ref.id));
    case "item": {
      const item = db.state.items.find((i) => i.id === entry.ref.id);
      if (!item) return false;
      if (step === "check" && !unconfirmed(item)) return false;
      return entry.date_role === "done" ? item.status === "done" : item.status === "open" || item.status === "snoozed";
    }
    case "contract":
      return db.state.contracts.some((c) => c.id === entry.ref.id && c.status === "active");
    case "draft":
      // Waiting for: a sent letter no longer waited for once the visitor says it was answered
      if (step === "waiting") return db.state.drafts.some((d) => d.id === entry.ref.id && d.status === "sent" && !d.answered_on);
      return db.state.drafts.some((d) => d.id === entry.ref.id && (entry.date_role === "sent" || d.status !== "sent"));
    case "call":
      return db.state.calls.some((c) => c.id === entry.ref.id && !c.promise_kept_on);
    default:
      return true;
  }
}

const transfers = (e: WeekEntry) => e.date_role !== "collected" && e.date_role !== "at_appointment";

/**
 * A letter that waited for the visitor (from the watched folder) and was answered since — "Keep private"
 * in the demo: its row says what `week.py` says of it now (kept private and never read: look through it).
 */
function followLetter(db: MockDb, entry: WeekEntry): WeekEntry {
  if (entry.ref.type !== "document" || entry.status !== "held") return entry;
  const doc = db.document(entry.ref.id);
  if (!doc || doc.status === "held") return entry;
  const unread = doc.ai_private && !doc.ai_processed_at;
  return {
    ...entry,
    status: doc.status,
    note: unread ? "Kept private — not read, so look through it yourself." : "Nothing to do — filed.",
    tone: unread ? "neutral" : "ok",
  };
}

function followStep(db: MockDb, step: WeekStep): WeekStep {
  const entries = step.entries.filter((e) => stillThere(db, e, step.id)).map((e) => followLetter(db, e));
  if (entries.length === step.entries.length) return { ...step, entries };
  const total =
    step.id === "pay" ? entries.reduce((sum, e) => sum + (transfers(e) && (e.currency ?? "EUR") === "EUR" ? (e.amount ?? 0) : 0), 0) : step.total;
  return {
    ...step,
    entries,
    total: step.total === null ? null : Math.round((total ?? 0) * 100) / 100,
    summary: entries.length || step.more ? `${entries.length + step.more} left to look at` : "All done here",
  };
}

const DAY_MS = 86_400_000;
const addDays = (iso: string, days: number) => new Date(Date.parse(`${iso}T00:00:00Z`) + days * DAY_MS).toISOString().slice(0, 10);

/** The day Today suggests the session again after one done or dismissed on `day` (`prompt_due`): a week
 * on, or the first Sunday at least 4 days on. */
export function nextPromptDay(day: string): string {
  for (let n = 1; n < 7; n += 1) {
    const d = addDays(day, n);
    if (n >= 4 && new Date(`${d}T00:00:00Z`).getUTCDay() === 0) return d;
  }
  return addDays(day, 7);
}

/** The weekly session as it stands in the demo. */
export function mockWeek(db: MockDb): WeeklySession {
  const week = clone(MOCK_WEEK);
  const state = stateOf(db);
  const steps = week.steps.map((s) => followStep(db, s)).filter((s) => s.id !== "now" || s.entries.length > 0);
  // the ending's candidates as the real app ranks them (`week.deadlines`): the first one still open
  const ahead = MOCK_WEEK_DEADLINES.filter((e) => stillThere(db, e));
  const leftOverdue = new Set(week.steps.flatMap((s) => s.entries).filter((e) => e.overdue).map((e) => e.key));
  const stillOverdue = new Set(steps.flatMap((s) => s.entries).filter((e) => e.overdue).map((e) => e.key));
  const known = [state.lastSession, state.dismissed].filter((d): d is string => d !== null).sort();
  const last = known[known.length - 1];
  return {
    ...week,
    steps,
    next_deadline: ahead[0] ?? null,
    due_today: ahead.filter((e) => e.date === week.today).length,
    overdue: Math.max(0, week.overdue - (leftOverdue.size - stillOverdue.size)),
    last_session: state.lastSession,
    // "Finish" or "Not now" today: no prompt until the next one is due (the demo's today doesn't move)
    due: !last && steps.some((s) => s.entries.length > 0),
    next_prompt: last ? nextPromptDay(last) : null,
  };
}

export function mockWeekDone(db: MockDb): WeeklySession {
  stateOf(db).lastSession = db.today;
  db.log("week.done", "Weekly review done");
  return mockWeek(db);
}

export function mockWeekDismiss(db: MockDb): WeeklySession {
  stateOf(db).dismissed = db.today;
  return mockWeek(db);
}
